// Parse and validate conflict data
const webhookData = $input.first().json;

if (!webhookData.conflictId || !webhookData.userId || !webhookData.saveGameId) {
  throw new Error('Missing required conflict data');
}

// Extract conflict information
const conflictData = {
  conflict_id: webhookData.conflictId,
  user_id: webhookData.userId,
  save_game_id: webhookData.saveGameId,
  conflict_type: webhookData.conflictType || 'data_mismatch',
  platform_a: webhookData.platformA || 'unknown',
  platform_b: webhookData.platformB || 'unknown',
  severity: webhookData.severity || 'medium',
  detected_at: webhookData.timestamp || new Date().toISOString(),
  field_path: webhookData.fieldPath,
  data_a: webhookData.dataA || {},
  data_b: webhookData.dataB || {}
};

return [{
  json: conflictData
}];

// Analyze conflict and determine resolution strategy
const conflictData = $json;

function getRecommendedStrategy(conflictType, fieldPath, severity) {
  // Conflict resolution strategy logic
  if (conflictType === 'timestamp_mismatch' || conflictType === 'metadata_mismatch') {
    return 'last_write_wins';
  } else if (conflictType === 'experience_mismatch' || conflictType === 'level_mismatch') {
    return 'numeric_max';
  } else if (conflictType === 'inventory_mismatch' || conflictType === 'abilities_mismatch') {
    return 'union_merge';
  } else if (conflictType === 'progress_mismatch') {
    return 'manual_review';
  } else if (severity === 'low') {
    return 'smart_merge';
  } else if (severity === 'high') {
    return 'manual_review';
  } else {
    return 'platform_priority';
  }
}

function analyzeConflictComplexity(dataA, dataB) {
  const diff = require('deep-object-diff').diff;
  const differences = diff(dataA, dataB);

  let complexity = 0;
  let criticalFields = [];

  function analyzeObject(obj, path = '') {
    for (const [key, value] of Object.entries(obj)) {
      const fullPath = path ? `${path}.${key}` : key;

      if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        analyzeObject(value, fullPath);
      } else {
        complexity++;

        // Identify critical fields
        if (fullPath.includes('campaignState.chapter') || 
            fullPath.includes('characters.') && fullPath.includes('.level') ||
            fullPath.includes('quest')) {
          criticalFields.push(fullPath);
        }
      }
    }
  }

  analyzeObject(differences);

  return {
    complexity,
    criticalFields,
    autoResolvable: complexity < 5 && criticalFields.length === 0
  };
}

const analysis = analyzeConflictComplexity(conflictData.data_a, conflictData.data_b);
const recommendedStrategy = getRecommendedStrategy(
  conflictData.conflict_type, 
  conflictData.field_path, 
  conflictData.severity
);

return [{
  json: {
    ...conflictData,
    analysis: analysis,
    recommended_strategy: recommendedStrategy,
    auto_resolve_possible: analysis.autoResolvable && conflictData.severity !== 'high'
  }
}];

// Auto-resolve conflict using recommended strategy
const conflictData = $json;
const strategy = conflictData.recommended_strategy;

function applyResolutionStrategy(dataA, dataB, strategy) {
  switch (strategy) {
    case 'last_write_wins':
      const timestampA = new Date(dataA.metadata?.timestamp || 0);
      const timestampB = new Date(dataB.metadata?.timestamp || 0);
      return timestampA > timestampB ? dataA : dataB;

    case 'numeric_max':
      return resolveNumericMax(dataA, dataB);

    case 'union_merge':
      return unionMerge(dataA, dataB);

    case 'platform_priority':
      const priority = {
        'desktop': 1,
        'mobile_ios': 2,
        'mobile_android': 3,
        'web': 4,
        'vr_oculus': 5,
        'vr_htc': 6
      };
      const platformA = dataA.metadata?.platform || 'unknown';
      const platformB = dataB.metadata?.platform || 'unknown';
      return (priority[platformA] || 999) < (priority[platformB] || 999) ? dataA : dataB;

    case 'smart_merge':
      return smartMerge(dataA, dataB, conflictData.field_path);

    default:
      return dataA; // Fallback
  }
}

function resolveNumericMax(dataA, dataB) {
  const result = JSON.parse(JSON.stringify(dataA));

  function mergeNumericMax(target, source) {
    for (const [key, value] of Object.entries(source)) {
      if (typeof value === 'number' && typeof target[key] === 'number') {
        target[key] = Math.max(target[key], value);
      } else if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        if (!target[key] || typeof target[key] !== 'object') {
          target[key] = {};
        }
        mergeNumericMax(target[key], value);
      }
    }
  }

  mergeNumericMax(result, dataB);
  return result;
}

function unionMerge(dataA, dataB) {
  const result = JSON.parse(JSON.stringify(dataA));

  function mergeUnion(target, source) {
    for (const [key, value] of Object.entries(source)) {
      if (Array.isArray(value) && Array.isArray(target[key])) {
        target[key] = [...new Set([...target[key], ...value])];
      } else if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        if (!target[key] || typeof target[key] !== 'object') {
          target[key] = {};
        }
        mergeUnion(target[key], value);
      } else {
        target[key] = value;
      }
    }
  }

  mergeUnion(result, dataB);
  return result;
}

function smartMerge(dataA, dataB, fieldPath) {
  // Smart merge based on field patterns
  if (fieldPath?.includes('experiencePoints') || fieldPath?.includes('level')) {
    return resolveNumericMax(dataA, dataB);
  } else if (fieldPath?.includes('inventory') || fieldPath?.includes('abilities')) {
    return unionMerge(dataA, dataB);
  } else {
    // Default to last write wins
    return applyResolutionStrategy(dataA, dataB, 'last_write_wins');
  }
}

const resolvedData = applyResolutionStrategy(conflictData.data_a, conflictData.data_b, strategy);
const checksum = require('crypto').createHash('sha256').update(JSON.stringify(resolvedData)).digest('hex');

return [{
  json: {
    ...conflictData,
    resolved_data: resolvedData,
    resolution_strategy: strategy,
    checksum: checksum,
    resolved_at: new Date().toISOString(),
    auto_resolved: true
  }
}];

// Create new save version with resolved data
const conflictData = $json;

// Get next version number
const nextVersion = Date.now();

const saveVersionData = {
  save_game_id: conflictData.save_game_id,
  platform: 'resolved',
  device_id: 'conflict_resolution',
  data_json: JSON.stringify(conflictData.resolved_data),
  sync_version: nextVersion,
  is_current: true,
  data_hash: conflictData.checksum,
  metadata: JSON.stringify({
    resolved: true,
    strategy: conflictData.resolution_strategy,
    resolvedAt: conflictData.resolved_at,
    conflictId: conflictData.conflict_id
  })
};

return [{
  json: saveVersionData
}];

// Prepare notification for auto-resolved conflict
const conflictData = $json;

const notification = {
  type: 'conflict_auto_resolved',
  user_id: conflictData.user_id,
  conflict_id: conflictData.conflict_id,
  save_game_id: conflictData.save_game_id,
  resolution_strategy: conflictData.resolution_strategy,
  timestamp: conflictData.resolved_at,
  message: `Conflict automatically resolved using ${conflictData.resolution_strategy} strategy`
};

return [{
  json: notification
}];

// Prepare manual resolution request
const conflictData = $json;

const manualResolutionRequest = {
  type: 'conflict_manual_resolution_required',
  user_id: conflictData.user_id,
  conflict_id: conflictData.conflict_id,
  save_game_id: conflictData.save_game_id,
  conflict_type: conflictData.conflict_type,
  platform_a: conflictData.platform_a,
  platform_b: conflictData.platform_b,
  severity: conflictData.severity,
  field_path: conflictData.field_path,
  recommended_strategy: conflictData.recommended_strategy,
  analysis: conflictData.analysis,
  data_a_summary: summarizeData(conflictData.data_a),
  data_b_summary: summarizeData(conflictData.data_b),
  created_at: new Date().toISOString(),
  expires_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString() // 24 hours
};

function summarizeData(data) {
  const summary = {
    character_count: data.characters ? data.characters.length : 0,
    chapter: data.campaignState?.chapter || 'unknown',
    scene: data.campaignState?.scene || 'unknown',
    last_modified: data.metadata?.timestamp || 'unknown',
    platform: data.metadata?.platform || 'unknown'
  };

  if (data.characters && data.characters.length > 0) {
    summary.characters = data.characters.map(char => ({
      name: char.name,
      level: char.level,
      class: char.class
    }));
  }

  return summary;
}

return [{
  json: manualResolutionRequest
}];

// Log workflow completion statistics
const results = $input.all();
const stats = {
  total_conflicts: results.length,
  auto_resolved: results.filter(item => item.json.auto_resolved).length,
  manual_resolution_required: results.filter(item => !item.json.auto_resolved).length,
  execution_time: new Date().toISOString()
};

console.log('Conflict Resolution Workflow completed:', stats);

// Update metrics in Redis
const redis = require('ioredis');
const redisClient = new redis({
  host: 'localhost',
  port: 6379,
  password: process.env.REDIS_PASSWORD
});

redisClient.hmset('conflict_resolution_stats', {
  last_execution: stats.execution_time,
  total_processed: stats.total_conflicts,
  auto_resolved: stats.auto_resolved,
  manual_required: stats.manual_resolution_required
});

redisClient.expire('conflict_resolution_stats', 86400);

redisClient.quit();

return [{
  json: {
    workflow: 'conflict-resolution',
    statistics: stats,
    timestamp: new Date().toISOString()
  }
}];

// Handle existing conflict (already resolved or being processed)
const existingConflict = $json;

if (existingConflict.is_resolved) {
  // Conflict already resolved - log and exit
  return [{
    json: {
      message: 'Conflict already resolved',
      conflict_id: existingConflict.id,
      resolution_strategy: existingConflict.resolution_strategy,
      action: 'none_required'
    }
  }];
} else {
  // Conflict exists but not resolved - continue with analysis
  return [{
    json: {
      message: 'Existing conflict detected',
      conflict_id: existingConflict.id,
      action: 'continue_processing'
    }
  }];
}
